import { randomBytes } from 'node:crypto';

import fc from 'fast-check';
import { describe, expect, it } from 'vitest';

import { SLUG_PATTERN } from '@links/shared';

import {
  BASE62,
  customSlugIssue,
  generateSlug,
  GENERATED_SLUG_LENGTH,
  RESERVED_SLUGS,
} from './slug';

describe('generateSlug', () => {
  it('produces 7 base62 characters that pass the slug grammar', () => {
    fc.assert(
      fc.property(fc.uint8Array({ minLength: 64, maxLength: 64 }), (bytes) => {
        let offset = 0;
        const fake = (size: number) => {
          // Replay the generated bytes, then fall back to a byte that is never
          // rejected, so a run of 248+ bytes cannot loop forever.
          const out = new Uint8Array(size).fill(1);
          out.set(bytes.subarray(offset, offset + size));
          offset += size;
          return out;
        };
        const slug = generateSlug(fake);
        expect(slug).toHaveLength(GENERATED_SLUG_LENGTH);
        expect(SLUG_PATTERN.test(slug)).toBe(true);
      }),
      { seed: 9, numRuns: 500 },
    );
  });

  it('discards bytes at or above 248 instead of folding them onto the first characters', () => {
    // 248..255 would map to "0".."7" under a bare modulo. All rejected, then 61 -> "z".
    const bytes = [248, 249, 250, 251, 252, 253, 254, 255, 61, 61, 61, 61, 61, 61, 61];
    let offset = 0;
    const fake = (size: number) => {
      const out = new Uint8Array(bytes.slice(offset, offset + size));
      offset += size;
      return out.length === size ? out : new Uint8Array(size).fill(61);
    };
    expect(generateSlug(fake)).toBe('zzzzzzz');
  });

  it('is close to uniform over the alphabet (chi-square, 62,000 characters)', () => {
    const counts = new Map<string, number>();
    for (let i = 0; i < 62_000 / GENERATED_SLUG_LENGTH; i += 1) {
      for (const char of generateSlug(randomBytes)) counts.set(char, (counts.get(char) ?? 0) + 1);
    }
    const total = [...counts.values()].reduce((a, b) => a + b, 0);
    const expected = total / BASE62.length;
    const chi = [...BASE62].reduce(
      (sum, c) => sum + ((counts.get(c) ?? 0) - expected) ** 2 / expected,
      0,
    );
    // 61 degrees of freedom: p = 0.001 critical value is 100.9. A bare modulo
    // with 256 byte values scores in the hundreds at this sample size.
    expect(chi).toBeLessThan(100.9);
  });
});

describe('customSlugIssue', () => {
  it('accepts a readable custom slug', () => {
    expect(customSlugIssue('spring-sale')).toBeNull();
  });

  it('refuses reserved words in any case', () => {
    for (const word of ['health', 'Health', 'METRICS', 'Admin']) {
      expect(customSlugIssue(word), word).toBe('reserved');
    }
  });

  it('reports grammar before policy', () => {
    expect(customSlugIssue('a/b')).toBe('grammar');
    expect(customSlugIssue('ab')).toBe('grammar');
  });

  it('every reserved word would otherwise pass the grammar, so none is dead weight', () => {
    for (const word of RESERVED_SLUGS) expect(SLUG_PATTERN.test(word), word).toBe(true);
  });
});
